// Render antialiased Questrial text
pub fn drawText(surface: *fb.Surface, text: []const u8, x: i32, y: i32, color: u32) void {
    var cur_x = x;
    for (text) |c| {
        if (c >= 32 and c <= 126) {
            const g = GLYPHS[c - 32];
            if (g.width > 0 and g.height > 0) {
                const gx = cur_x + g.offset_x;
                const gy = y + g.offset_y;
                var row: usize = 0;
                while (row < g.height) : (row += 1) {
                    const py = gy + @as(i32, @intCast(row));
                    var col: usize = 0;
                    while (col < g.width) : (col += 1) {
                        const px = gx + @as(i32, @intCast(col));
                        const alpha = GLYPH_BITMAPS[g.bitmap_offset + row * g.width + col];
                        if (alpha > 0) {
                            if (alpha == 255) {
                                surface.setPixel(px, py, color);
                            } else {
                                const bg = surface.getPixel(px, py);
                                surface.setPixel(px, py, fb.blendPixel(bg, color, alpha));
                            }
                        }
                    }
                }
            }
            cur_x += g.advance;
        } else if (c == ' ') {
            cur_x += 6;
        } else if (c == '\t') {
            cur_x += 24;
        }
    }
}

// Draw antialiased Questrial text with 1px drop shadow
pub fn drawTextWithShadow(surface: *fb.Surface, text: []const u8, x: i32, y: i32, fg_color: u32, shadow_color: u32) void {
    // 1. Draw subtle drop shadow (+1, +1)
    drawText(surface, text, x + 1, y + 1, shadow_color);
    // 2. Draw crisp foreground text
    drawText(surface, text, x, y, fg_color);
}

// Measure exact rendered pixel width of string
pub fn measureString(text: []const u8) u32 {
    var cur_w: u32 = 0;
    for (text) |c| {
        if (c >= 32 and c <= 126) {
            cur_w += GLYPHS[c - 32].advance;
        } else if (c == ' ') {
            cur_w += 6;
        } else if (c == '\t') {
            cur_w += 24;
        }
    }
    return cur_w;
}
